package com.nanless.paperdigest.ui
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.math.BigInteger
class StudyRecordPresentationTest {
 private fun research(id:String="session",owner:String="paper")=JSONObject().put("id",id).put("paperID",owner).put("kind","study").put("status","completed").put("inputContract","android-study-input-v1").put("answer","saved answer").put("source",JSONObject().put("paperID",owner).put("kind","pdf-page").put("pages",org.json.JSONArray(listOf(5))).put("sourceVersion","v1"))
 private fun job(id:String="session",owner:String="paper",kind:String="model.run")=JSONObject().put("id",id).put("paperID",owner).put("kind",kind)
 @Test fun responsesChatAndSavedCamelUseSameReadableCounts(){val values=listOf(JSONObject("{\"input_tokens\":3,\"output_tokens\":4,\"total_tokens\":7}"),JSONObject("{\"prompt_tokens\":3,\"completion_tokens\":4,\"total_tokens\":7}"),JSONObject("{\"inputTokens\":3,\"outputTokens\":4,\"totalTokens\":7}"));for(u in values){assertEquals("输入：3 · 输出：4 · 合计：7 Token",studyUsage(u).label())}}
 @Test fun missingCountsNeverBecomeZeroOrCalculatedTotal(){val value=studyUsage(JSONObject().put("input_tokens",0).put("output_tokens",4));assertEquals(0L,value.input.value);assertEquals(4L,value.output.value);assertNull(value.total.value);assertFalse(value.total.problem);assertTrue(value.label().contains("合计：未知"))}
 @Test fun matchingAliasesAreAcceptedButConflictsNotPicked(){assertEquals(3L,studyUsage(JSONObject().put("input_tokens",3).put("promptTokens",3)).input.value);val conflict=studyUsage(JSONObject().put("input_tokens",3).put("prompt_tokens",4));assertNull(conflict.input.value);assertTrue(conflict.input.problem)}
 @Test fun invalidAliasCannotHideBehindValidOne(){val result=studyUsage(JSONObject().put("input_tokens",3).put("inputTokens","3"));assertNull(result.input.value);assertTrue(result.input.problem)}
 @Test fun tokenCountsRequireRealNonnegativeIntegralNumbers(){for(value in listOf<Any>(-1,1.0,1.5,"3",true,JSONObject.NULL,BigInteger.valueOf(Long.MAX_VALUE).add(BigInteger.ONE))){val result=studyUsage(JSONObject().put("input_tokens",value));assertNull(result.input.value);assertTrue(result.input.problem)}}
 @Test fun inconsistentOriginalTotalIsUnknownNotRecomputed(){val result=studyUsage(JSONObject().put("input_tokens",3).put("output_tokens",4).put("total_tokens",99));assertEquals(3L,result.input.value);assertEquals(4L,result.output.value);assertNull(result.total.value);assertTrue(result.total.problem);assertFalse(result.label().contains("99"));assertFalse(result.label().contains("合计：7"))}
 @Test fun noOverflowWhenCheckingOriginalTotals(){val result=studyUsage(JSONObject().put("input_tokens",Long.MAX_VALUE).put("output_tokens",1).put("total_tokens",0));assertEquals(Long.MAX_VALUE,result.input.value);assertNull(result.total.value);assertTrue(result.total.problem)}
 @Test fun usageParsingNeverChangesOriginalJson(){val u=JSONObject().put("input_tokens",3).put("extra",JSONObject().put("cached",2));val before=u.toString();studyUsage(u).label();assertEquals(before,u.toString())}
 @Test fun missingOrNonObjectUsageIsReadableUnknown(){assertEquals("输入：未知 · 输出：未知 · 合计：未知 Token",sessionUsageLabel(JSONObject().put("usage","raw unsupported")));assertEquals(studyUsage(null).label(),sessionUsageLabel(JSONObject()))}
 @Test fun exactAndroidResearchTaskBindsOriginalOnly(){val s=research().put("usage",JSONObject().put("input_tokens",5));assertSame(s,taskStudySession(job(),listOf(s)));val p=studyTaskPresentation(job(),listOf(s))!!;assertTrue(p.evidence.contains("物理页 5"));assertTrue(p.usage.contains("输入：5"))}
 @Test fun explicitNavigationDoesNotGrantDifferentTaskFee(){val s=research("old");val j=job("new").put("sessionID","old").put("usage",JSONObject().put("total_tokens",999));assertSame(s,jobSession(j,listOf(s)));assertNull(taskStudySession(j,listOf(s)));assertFalse(studyTaskPresentation(j,listOf(s))!!.usage.contains("999"))}
 @Test fun noOriginalNeverBorrowsRawJobUsageOrCurrentPaper(){val j=job().put("usage",JSONObject().put("input_tokens",999)).put("material",JSONObject().put("sha256","raw"));assertNull(taskStudySession(j,emptyList()));assertEquals(studyUsage(null).label(),studyTaskPresentation(j,emptyList())!!.usage)}
 @Test fun mismatchedOwnerAndPurposeRefuseFees(){val s=research();assertNull(taskStudySession(job(owner="other"),listOf(s)));assertNull(taskStudySession(job(kind="model.check"),listOf(s)));assertNull(taskStudySession(job().put("paperID",JSONObject.NULL),listOf(s)))}
 @Test fun nonModelExplicitPointerIsOnlyNavigation(){val s=research();val j=job(kind="zotero.archive").put("sessionID","session").put("usage",JSONObject().put("input_tokens",999));assertSame(s,jobSession(j,listOf(s)));assertNull(taskStudySession(j,listOf(s)));assertNull(studyTaskPresentation(j,listOf(s)))}
 @Test fun androidConnectionCheckShapeIsRecognizedExactly(){val s=research(owner="configuration-check").put("source",JSONObject().put("paperID","configuration-check").put("kind","connection-check"));val j=job(owner="configuration-check",kind="model.check");assertSame(s,taskStudySession(j,listOf(s)));assertNull(taskStudySession(j,listOf(JSONObject(s.toString()).removeAndReturn("inputContract"))));assertNull(taskStudySession(job(owner="configuration-check"),listOf(s)))}
 @Test fun restoredMacConnectionCheckAndStudyRemainReadOnlyRecognized(){val check=JSONObject().put("id","check").put("paperID","").put("kind","connection-check").put("source",JSONObject().put("kind","connection-check"));assertSame(check,taskStudySession(job("check","","model.check"),listOf(check)));val study=research().removeAndReturn("inputContract").put("status","complete");assertSame(study,taskStudySession(job(),listOf(study)))}
 @Test fun reuseNeverRecountsOldUsageAsNewTask(){val j=job().put("result",JSONObject().put("reused",true)).put("usage",JSONObject().put("input_tokens",999));val p=studyTaskPresentation(j,listOf(research().put("usage",JSONObject().put("input_tokens",99))))!!;assertTrue(p.usage.contains("未新增模型请求"));assertFalse(p.usage.contains("99"));assertTrue(p.charge.contains("原请求金额未在本任务核对"))}
 @Test fun conflictingOrMalformedRoutesCannotGrantFeesOrReuse(){val s=research();for(j in listOf(job().put("command","model.check"),job().put("kind",4).put("command","model.run"))){assertNull(taskStudySession(j,listOf(s)));assertEquals(studyUsage(null).label(),studyTaskPresentation(j.put("result",JSONObject().put("reused",true)),listOf(s))!!.usage)}}
 @Test fun bothLegacySuccessNamesMayAppendButFailuresOrChecksCannot(){for(status in listOf("complete","completed")){assertTrue(canAppendSavedSession(research().put("status",status)))};for(status in listOf("failed","cancelled","pending")){assertFalse(canAppendSavedSession(research().put("status",status)))};assertFalse(canAppendSavedSession(research(owner="configuration-check")));assertFalse(canAppendSavedSession(research().put("kind","connection-check")));assertFalse(canAppendSavedSession(research().put("answer",JSONObject())))}
 @Test fun appendLookupRequiresUniqueExactIdentityAndOriginalNoteFieldsRemain(){val s=research();assertSame(s,uniqueStudySession(listOf(s),"session"));assertNull(uniqueStudySession(listOf(s,JSONObject(s.toString())),"session"));val original=s.toString();assertTrue(noteFromSession(s).contains("saved answer"));assertEquals(original,s.toString())}
 @Test fun trueKnownCostMustBeFiniteNonnegativeNumericAndIsNotCurrencyGuess(){assertEquals("原记录金额：0（币种未核验）",sessionChargeLabel(research().put("costKnown",true).put("cost",0)));assertTrue(sessionChargeLabel(research().put("costKnown",true).put("cost",1.25)).contains("1.25"));assertEquals("金额未确认，不表示免费",sessionChargeLabel(research().put("costKnown",false).put("cost",0)))}
 @Test fun readerIndexExcludesAllDuplicatesAndInvalidOwnersWithoutChangingOrderOrBytes(){val first=research("one");val duplicate=research("two");val invalid=research("bad").put("source",JSONObject().put("paperID","other"));val last=research("last");val rows=listOf(first,duplicate,JSONObject(duplicate.toString()),invalid,last);val before=rows.map{it.toString()};val index=uniqueStudySessionIndex(rows);assertEquals(listOf("one","last"),index.keys.toList());assertSame(first,index["one"]);assertEquals(before,rows.map{it.toString()})}
 @Test fun onlyActualNonblankStringIsPresentedAsActualModel(){val s=research().put("model","requested").put("actualModel","actual-returned");val before=s.toString();assertEquals("实际模型：actual-returned",sessionModelLabel(s));assertEquals(before,s.toString())}
 @Test fun oldMacAndAndroidRequestedModelNeverMasqueradeAsActual(){for(s in listOf(research().removeAndReturn("inputContract").put("status","complete"),research())){s.put("model","muse-spark-1.3-contributor");val before=s.toString();assertEquals("请求模型：muse-spark-1.3-contributor；实际模型未记录",sessionModelLabel(s));assertEquals(before,s.toString())}}
 @Test fun absentBlankOrWrongTypeActualUsesExplicitRequestedOnlyLabel(){for(value in listOf<Any>("","   ",123,true,JSONObject(),JSONObject.NULL)){val s=research().put("model","requested").put("actualModel",value);assertEquals("请求模型：requested；实际模型未记录",sessionModelLabel(s))}}
 @Test fun absentBlankOrWrongTypeRequestWithNoActualIsUnknown(){for(value in listOf<Any>("","   ",123,true,JSONObject(),JSONObject.NULL)){assertEquals("请求模型与实际模型均未记录",sessionModelLabel(research().put("model",value)))};assertEquals("请求模型与实际模型均未记录",sessionModelLabel(research()))}
 @Test fun explicitNullOrAndroidContractOnMacCheckDoesNotInventLegacyProvenance(){assertNull(taskStudySession(job(),listOf(research().put("inputContract",JSONObject.NULL))));val macCheck=JSONObject().put("id","check").put("paperID","").put("kind","connection-check").put("source",JSONObject().put("kind","connection-check"));for(value in listOf<Any>(4,false,JSONObject.NULL,"android-study-input-v1")){assertNull(taskStudySession(job("check","","model.check"),listOf(JSONObject(macCheck.toString()).put("inputContract",value))))}}
 private fun JSONObject.removeAndReturn(key:String):JSONObject{remove(key);return this}
}
